formulas.expression:
if({!$Record.Website_Go_Live_Date_Time__c} != {!$Record__Prior.Website_Go_Live_Date_Time__c}, 
"Website Go Live Date/Time Changed: "& Text({!$Record.Website_Go_Live_Date_Time__c}) &BR(), "") &

if({!$Record.Digital_Dealer_Approved__c} != {!$Record__Prior.Digital_Dealer_Approved__c}, "Digital - Dealer Approved: "&if({!$Record.Digital_Dealer_Approved__c}, "Checked", "Unchecked") &BR(), "") &

if({!$Record.Offers_Inventory__c} != {!$Record__Prior.Offers_Inventory__c}, "Offers + Inventory: "&if({!$Record.Offers_Inventory__c}, "Checked", "Unchecked") &BR(), "") &

if( Text({!$Record.In_program_selection__c}) !=  Text({!$Record__Prior.In_program_selection__c}), 
"In program selection Changed: "& Text({!$Record.In_program_selection__c}) &BR(), "") &

if({!$Record.CallRevu_Number_Sales__c} != {!$Record__Prior.CallRevu_Number_Sales__c}, 
"CallRevu Number - Sales Changed: "& {!$Record.CallRevu_Number_Sales__c} &BR(), "") &

if({!$Record.CallRevu_Number_Service__c} != {!$Record__Prior.CallRevu_Number_Service__c}, 
"CallRevu Number - Service Changed: "& {!$Record.CallRevu_Number_Service__c} &BR(), "") &

if({!$Record.Business_License__c} != {!$Record__Prior.Business_License__c}, "Business License : "&if({!$Record.Business_License__c}, "Checked", "Unchecked") &BR(), "") &

if({!$Record.Digital_Brand_Diffs_Completed__c} != {!$Record__Prior.Digital_Brand_Diffs_Completed__c}, "Digital Brand Diffs Completed: "&if({!$Record.Digital_Brand_Diffs_Completed__c}, "Checked", "Unchecked") &BR(), "") &

if({!$Record.CRM_Email_for_Facebook_Leads__c} != {!$Record__Prior.CRM_Email_for_Facebook_Leads__c}, 
"CRM Email for Facebook Leads Changed: "& {!$Record.CRM_Email_for_Facebook_Leads__c} &BR(), "") &

if({!$Record.Vehicle_Ads_Tag__c} != {!$Record__Prior.Vehicle_Ads_Tag__c}, 
"Vehicle Ads Tag Changed: "& {!$Record.Vehicle_Ads_Tag__c} &BR(), "") &

if({!$Record.GTM_Code__c} != {!$Record__Prior.GTM_Code__c}, 
"GTM Code Changed: "& {!$Record.GTM_Code__c} &BR(), "") &

if(Text({!$Record.Google_Ads_Account__c}) != Text({!$Record__Prior.Google_Ads_Account__c}), 
"Digital Account Type Changed: "& Text({!$Record.Google_Ads_Account__c}) &BR(), "") &

if(Text({!$Record.Billing_Section__c}) != Text({!$Record__Prior.Billing_Section__c}), 
"Billing Section Changed: "& Text({!$Record.Billing_Section__c}) &BR(), "") &

if(Text({!$Record.Service_Coupons_Selected__c}) != Text({!$Record__Prior.Service_Coupons_Selected__c}), 
"Service Coupons Selected Changed: "& Text({!$Record.Service_Coupons_Selected__c}) &BR(), "") &

if({!$Record.Measurement_ID__c} != {!$Record__Prior.Measurement_ID__c}, 
"Measurement ID Changed: "& {!$Record.Measurement_ID__c} &BR(), "")

